  'backup': 'النسخ الاحتياطي',
};

const ACTION_LABELS: Record<string, string> = {
  create: 'إضافة',
  update: 'تعديل',
  delete: 'حذف',
};

export async function activityLogger(req: AuthRequest, res: Response, next: NextFunction): Promise<void> {
  const originalSend = res.send.bind(res);

  res.send = function (body: any): Response {
    // فقط للطلبات الناجحة
    const isSuccess = res.statusCode >= 200 && res.statusCode < 300;
    const method = req.method;

    if (isSuccess && ['POST', 'PUT', 'DELETE'].includes(method) && req.user) {
      const urlPath = req.path.split('/').filter(Boolean)[0] || '';
      const moduleLabel = MODULE_MAP[urlPath];

      // تجاهل مسارات المصادقة والملفات
      if (moduleLabel && !urlPath.startsWith('auth') && !urlPath.startsWith('files')) {
        let action: 'create' | 'update' | 'delete' = 'create';
        if (method === 'PUT') action = 'update';
        else if (method === 'DELETE') action = 'delete';

        let detail = '';
        try {
          const parsed = typeof body === 'string' ? JSON.parse(body) : body;
          const data = parsed?.data || parsed;
          if (action === 'create') {
            detail = data?.name || data?.caseNumber || data?.title || data?.announcementNumber || '';
          }
        } catch { /* ignore */ }

        const description = detail
          ? `${ACTION_LABELS[action]} ${moduleLabel}${detail ? `: ${detail}` : ''}`
          : `${ACTION_LABELS[action]} في ${moduleLabel}`;

        ActivityLog.create({
          userId: req.user.id,
          userName: req.user.name,
          action,
          module: urlPath,
          moduleLabel,
          description,
          read: false,
        }).then((log) => {
          io.emit('newActivity', log);
        }).catch(() => { /* ignore */ });
      }
    }

    return originalSend(body);
  } as any;

  next();
}

import { Request, Response } from 'express';
import mongoose from 'mongoose';
import { getBucket } from '../config/database';
import { Readable } from 'stream';

// رفع ملف إلى GridFS
export async function uploadFile(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ success: false, message: 'لم يتم رفع أي ملف' });
      return;
    }

    const bucket = getBucket();
    const fileId = new mongoose.Types.ObjectId();

    const uploadStream = bucket.openUploadStreamWithId(fileId, req.file.originalname, {
      contentType: req.file.mimetype,
      metadata: {
        originalName: req.file.originalname,
        size: req.file.size,
      },
    });

    const bufferStream = new Readable();
    bufferStream.push(req.file.buffer);
    bufferStream.push(null);

    bufferStream
      .pipe(uploadStream)
      .on('error', (error) => {
        console.error('خطأ في رفع الملف:', error);
        res.status(500).json({ success: false, message: 'فشل رفع الملف' });
      })
      .on('finish', () => {
        res.status(200).json({
          success: true,
          data: {
            fileId: fileId.toString(),
            fileName: req.file!.originalname,
            fileSize: req.file!.size,
          },
        });
      });
  } catch (error) {
    console.error('خطأ:', error);
    res.status(500).json({ success: false, message: 'خطأ داخلي' });
  }
}

// تحديد Content-Type من امتداد الملف
function getContentType(filename: string): string {
  const ext = filename.split('.').pop()?.toLowerCase() || '';
  const types: Record<string, string> = {
    pdf: 'application/pdf',
    jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif',
    bmp: 'image/bmp', webp: 'image/webp', svg: 'image/svg+xml',
    doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls: 'application/vnd.ms-excel', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    ppt: 'application/vnd.ms-powerpoint', pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    txt: 'text/plain', html: 'text/html', csv: 'text/csv',
    mp4: 'video/mp4', avi: 'video/x-msvideo', mkv: 'video/x-matroska',
    mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg',
    zip: 'application/zip', rar: 'application/x-rar-compressed',
  };
  return types[ext] || 'application/octet-stream';
}

// تحميل ملف من GridFS
export async function downloadFile(req: Request, res: Response): Promise<void> {
  try {
    const { id } = req.params;
    const bucket = getBucket();
    const fileId = new mongoose.Types.ObjectId(id);

    const files = await bucket.find({ _id: fileId }).toArray();
    if (files.length === 0) {
      res.status(404).json({ success: false, message: 'الملف غير موجود' });
      return;
    }

    const file = files[0];
    const contentType = (file.contentType && file.contentType !== 'application/octet-stream')
      ? file.contentType
      : getContentType(file.filename);
    res.set('Content-Type', contentType);
    res.set('Content-Disposition', `inline; filename="${encodeURIComponent(file.filename)}"`);

    bucket
      .openDownloadStream(fileId)
      .on('error', (error) => {
        console.error('خطأ في تحميل الملف:', error);
        res.status(500).json({ success: false, message: 'فشل تحميل الملف' });
      })
      .pipe(res);
  } catch (error) {
    console.error('خطأ:', error);
    res.status(500).json({ success: false, message: 'خطأ داخلي' });
  }
}

// حذف ملف من GridFS
export async function deleteFile(fileId: string): Promise<void> {
  try {
    const bucket = getBucket();
    await bucket.delete(new mongoose.Types.ObjectId(fileId));
  } catch (error) {
    console.error('تحذير: تعذر حذف الملف من GridFS:', fileId, error);
  }
}

